/** Повертає рядок SVG. fill=true — заповнений стиль (активний пункт). */
export function icon(name, { fill = false, size = 24, label = '' } = {}) {
  const p = ICONS[name] || ICONS['question'];
  const a = label ? `role="img" aria-label="${label}"` : 'aria-hidden="true"';
  return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 256 256" fill="currentColor" ${a}>${p[fill ? 1 : 0]}</svg>`;
}
